function control(state) {
  var tip = state.tip;
  var tgt = state.target;
  if (!tip || !tgt) {
    return { action: "stop", reason: "missing tip or target" };
  }
  var e = [tgt[0] - tip[0], tgt[1] - tip[1]];
  var err = Math.sqrt(e[0] * e[0] + e[1] * e[1]);
  if (!isFinite(err)) {
    return { action: "stop", reason: "non-finite error" };
  }
  if (err <= state.tolerancePx) {
    return { action: "verify" };
  }
  var h = state.history || [];
  var samples = [];
  for (var i = Math.max(0, h.length - 20); i < h.length; i++) {
    var s = h[i];
    if (!s || !s.applied || !s.delta || !s.command) continue;
    var a = s.applied;
    var d = s.delta;
    if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    if (Math.abs(a[0]) + Math.abs(a[1]) < 1e-9) continue;
    samples.push(s);
  }

  // Exploration helper: pick the axis move used least in recent history, preferring alignment with error.
  var cands = [[0.1, 0], [-0.1, 0], [0, 0.1], [0, -0.1]];
  var probeOut = function () {
    var best = null, bestScore = 1e9;
    for (var c = 0; c < cands.length; c++) {
      var cnt = 0;
      for (var j = Math.max(0, h.length - 12); j < h.length; j++) {
        var cm = h[j] && h[j].command;
        if (cm && Math.abs(cm[0] - cands[c][0]) < 1e-9 && Math.abs(cm[1] - cands[c][1]) < 1e-9) cnt++;
      }
      var dot = (cands[c][0] * e[0] + cands[c][1] * e[1]) / (err || 1);
      var score = cnt - 0.1 * dot;
      if (score < bestScore) { bestScore = score; best = cands[c]; }
