    return { action: "move", u: [best[0], best[1]] };
  };

  if (samples.length < 2) {
    return probeOut();
  }

  // Detect stall: last two commands produced almost no image motion.
  var stall = true;
  var nRecent = Math.min(2, h.length);
  for (var r = h.length - nRecent; r < h.length; r++) {
    var hs = h[r];
    if (!hs || !hs.delta || !hs.command) { stall = false; break; }
    var mag = Math.abs(hs.delta[0]) + Math.abs(hs.delta[1]);
    var cmagn = Math.abs(hs.command[0]) + Math.abs(hs.command[1]);
    if (cmagn < 1e-9 || mag > 0.5) { stall = false; break; }
  }
