  var sd0a0 = 0, sd0a1 = 0, sd1a0 = 0, sd1a1 = 0;
  for (var k = 0; k < samples.length; k++) {
    var ak = samples[k].applied;
    var dk = samples[k].delta;
    saa0 += ak[0] * ak[0];
    saa1 += ak[0] * ak[1];
    saa3 += ak[1] * ak[1];
    sd0a0 += dk[0] * ak[0];
    sd0a1 += dk[0] * ak[1];
    sd1a0 += dk[1] * ak[0];
    sd1a1 += dk[1] * ak[1];
