    return probeOut();
  }
  var J00 = (sd0a0 * saa3 - sd0a1 * saa1) / det;
  var J01 = (-sd0a0 * saa1 + sd0a1 * saa0) / det;
  var J10 = (sd1a0 * saa3 - sd1a1 * saa1) / det;
  var J11 = (-sd1a0 * saa1 + sd1a1 * saa0) / det;
  var jd = J00 * J11 - J01 * J10;
  if (!(Math.abs(jd) > 1e-6) || !isFinite(jd)) {
    return probeOut();
  }
  var a0 = (J11 * e[0] - J01 * e[1]) / jd;
  var a1 = (-J10 * e[0] + J00 * e[1]) / jd;
  var m = Math.max(Math.abs(a0), Math.abs(a1));
  if (!(m > 0) || !isFinite(m)) {
    return probeOut();
  }
  var scale = Math.min(1, 0.1 / m);
  if (err < 20) {
    scale *= 0.6;
  }
  var u0 = Math.max(-0.1, Math.min(0.1, a0 * scale));
  var u1 = Math.max(-0.1, Math.min(0.1, a1 * scale));
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "stop", reason: "non-finite control" };
  }
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tol = state.tolerancePx || 7;
  var tip = state.tip;
  var tgt = state.target;
  if (!tip || !tgt || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(tgt[0]) || !isFinite(tgt[1])) {
    return { action: 'stop', reason: 'non-finite measurement' };
  }
