  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (err <= tol) return { action: 'verify' };

  var hist = state.history || [];
  var n = hist.length;

  function sg(x) { return x < 0 ? -1 : 1; }

  function probe(c) {
    var sgn = 1;
    for (var j = n - 1; j >= 0 && j >= n - 6; j--) {
      var h = hist[j];
      if (!h || !h.command || !h.applied) continue;
      var cmd = h.command[c];
      if (typeof cmd !== 'number' || Math.abs(cmd) < 1e-9) continue;
      var ap = h.applied[c];
      if (typeof ap !== 'number' || !isFinite(ap) || Math.abs(ap) < 0.5 * Math.abs(cmd)) {
        sgn = -sg(cmd);
      } else {
        sgn = sg(cmd);
      }
      break;
    }
    var u = [0, 0];
    u[c] = 0.1 * sgn;
    return { action: 'move', u: u };
  }

  // Local Jacobian from the most recent window only (pose-dependent mapping)
  var start = Math.max(0, n - 12);
  var saa00 = 0, saa01 = 0, saa11 = 0;
  var sda00 = 0, sda01 = 0, sda10 = 0, sda11 = 0;
  var cnt = 0;
  for (var i = start; i < n; i++) {
    var h = hist[i];
    if (!h || !h.applied || !h.delta) continue;
    var a0 = h.applied[0], a1 = h.applied[1];
    var d0 = h.delta[0], d1 = h.delta[1];
    if (![a0, a1, d0, d1].every(function (v) { return typeof v === 'number' && isFinite(v); })) continue;
    if (Math.abs(a0) + Math.abs(a1) < 1e-9) continue;
    cnt++;
    saa00 += a0 * a0;
    saa01 += a0 * a1;
    saa11 += a1 * a1;
    sda00 += d0 * a0;
    sda01 += d0 * a1;
    sda10 += d1 * a0;
    sda11 += d1 * a1;
  }

  var ecol = (saa00 <= saa11) ? 0 : 1;
  if (cnt === 0) ecol = n % 2;

  // Last command blocked at a limit: probe instead of pushing into the limit
  if (n > 0) {
    var last = hist[n - 1];
    if (last && last.command && last.applied) {
      var cmdMag = Math.abs(last.command[0]) + Math.abs(last.command[1]);
      var apMag = Math.abs(last.applied[0]) + Math.abs(last.applied[1]);
      if (cmdMag > 1e-9 && apMag < 0.5 * cmdMag) {
        return probe(ecol);
      }
    }
  }

  if (cnt < 2) return probe(ecol);

  saa00 += 1e-4;
  saa11 += 1e-4;
  var sdet = saa00 * saa11 - saa01 * saa01;
  if (!isFinite(sdet) || Math.abs(sdet) < 1e-12) return probe(ecol);
  var i00 = saa11 / sdet, i01 = -saa01 / sdet, i11 = saa00 / sdet;

  var J00 = sda00 * i00 + sda01 * i01;
  var J01 = sda00 * i01 + sda01 * i11;
  var J10 = sda10 * i00 + sda11 * i01;
  var J11 = sda10 * i01 + sda11 * i11;
  var jdet = J00 * J11 - J01 * J10;
  var jscale = Math.abs(J00) + Math.abs(J01) + Math.abs(J10) + Math.abs(J11);
  if (!isFinite(jdet) || !isFinite(jscale) || jscale === 0 || Math.abs(jdet) < 1e-6 * jscale * jscale) {
    return probe(ecol);
  }

  var u0 = (J11 * ex - J01 * ey) / jdet;
  var u1 = (-J10 * ex + J00 * ey) / jdet;
  if (!isFinite(u0) || !isFinite(u1)) return probe(ecol);

  // Gain: full Newton step far away, damped near target to avoid chatter
  var g = Math.min(1, Math.max(0.35, err / 30));
  u0 *= g;
  u1 *= g;

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) {
    u0 = u0 * 0.1 / m;
    u1 = u1 * 0.1 / m;
  } else if (m > 0 && m < 0.01) {
    u0 = u0 * 0.01 / m;
    u1 = u1 * 0.01 / m;
  }
  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  return { action: 'move', u: [u0, u1] };
}

function control(state) {
  var tip = state.tip;
  var tgt = state.target;
  var ex = tgt[0] - tip[0];
  var ey = tgt[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (err <= state.tolerancePx) return { action: "verify" };
  if (typeof state.maxActions === "number" && typeof state.step === "number" && state.step >= state.maxActions) {
    return { action: "stop", reason: "action budget exhausted" };
  }
  var h = state.history || [];
  var probes = [[0.1, 0], [0, 0.1], [-0.1, 0], [0, -0.1]];
  var start = Math.max(0, h.length - 12);
  // Local linear model: delta = J * applied, fitted by regularized least squares on recent samples
  var m00 = 0, m01 = 0, m11 = 0; // sum a a^T
  var n00 = 0, n01 = 0, n10 = 0, n11 = 0; // sum d a^T
  var cnt = 0;
  for (var i = start; i < h.length; i++) {
    var s = h[i];
    if (!s || !s.applied || !s.delta) continue;
    var a0 = s.applied[0], a1 = s.applied[1], d0 = s.delta[0], d1 = s.delta[1];
    if (!isFinite(a0) || !isFinite(a1) || !isFinite(d0) || !isFinite(d1)) continue;
    if (s.limited) continue;
    m00 += a0 * a0; m01 += a0 * a1; m11 += a1 * a1;
    n00 += d0 * a0; n01 += d0 * a1;
    n10 += d1 * a0; n11 += d1 * a1;
    cnt++;
