  if (!excited) {
    return { action: "move", u: probes[h.length % 4].slice() };
  }
  // J = N * inv(M)
  var iM00 = mm11 / detM, iM01 = -m01 / detM, iM11 = mm00 / detM;
  var J00 = n00 * iM00 + n01 * iM01;
  var J01 = n00 * iM01 + n01 * iM11;
  var J10 = n10 * iM00 + n11 * iM01;
  var J11 = n10 * iM01 + n11 * iM11;
  var detJ = J00 * J11 - J01 * J10;
  if (!isFinite(detJ) || Math.abs(detJ) < 1e-9) {
    return { action: "move", u: probes[h.length % 4].slice() };
  }
  // u = inv(J) * e
  var u0 = (J11 * ex - J01 * ey) / detJ;
  var u1 = (-J10 * ex + J00 * ey) / detJ;
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "move", u: probes[h.length % 4].slice() };
  }
  var mag = Math.max(Math.abs(u0), Math.abs(u1));
  if (mag > 0) {
    var scale = 1;
    if (mag > 0.1) scale = 0.1 / mag;
    if (err < 25) scale *= Math.max(err / 25, 0.2);
    u0 *= scale;
    u1 *= scale;
  }
  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tip = state.tip, target = state.target;
  if (!tip || !target || !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(target[0]) || !isFinite(target[1])) {
    return { action: "stop", reason: "invalid tip or target" };
  }
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (err <= state.tolerancePx) {
    return { action: "verify" };
  }

  var h = state.history || [];
  var n = h.length;

