  if (n >= 3) {
    var stuck = true;
    for (var s = n - 3; s < n; s++) {
      var es = h[s];
      if (!es || !es.applied || !es.delta) { stuck = false; break; }
      var cas = es.applied, das = es.delta;
      var cmaxs = Math.max(Math.abs(cas[0]), Math.abs(cas[1]));
      var dnorms = Math.sqrt(das[0] * das[0] + das[1] * das[1]);
      if (!(cmaxs > 0.02 && dnorms < 0.5)) { stuck = false; }
    }
