      var lastS = h[n - 1].applied;
      var lm = Math.max(Math.abs(lastS[0]), Math.abs(lastS[1]));
      if (lm > 0) {
        var rx = -lastS[0] / lm * 0.1;
        var ry = -lastS[1] / lm * 0.1;
        if (isFinite(rx) && isFinite(ry)) return { action: "move", u: [rx, ry] };
      }
