    var e = h[i];
    if (!e || !e.applied || !e.delta || e.limited === true) continue;
    var c = e.applied, d = e.delta;
    if (!isFinite(c[0]) || !isFinite(c[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    if (Math.abs(c[0]) < 1e-9 && Math.abs(c[1]) < 1e-9) continue;
    valid.unshift(e);
  }
  var nv = valid.length;
  if (nv === 0) {
    var s0 = (n % 2 === 0) ? 0.1 : -0.1;
    return { action: "move", u: [s0, 0] };
  }

  var a11 = 0, a12 = 0, a22 = 0;
  var bx0 = 0, bx1 = 0, by0 = 0, by1 = 0;
  for (var j = 0; j < nv; j++) {
    var ee = valid[j];
    var cc = ee.applied, dd = ee.delta;
    var w = Math.pow(0.7, nv - 1 - j);
    a11 += w * cc[0] * cc[0];
    a12 += w * cc[0] * cc[1];
    a22 += w * cc[1] * cc[1];
    bx0 += w * dd[0] * cc[0];
    bx1 += w * dd[0] * cc[1];
    by0 += w * dd[1] * cc[0];
    by1 += w * dd[1] * cc[1];
  }

  // excitation when a channel has not been characterized in the local window
  if (a11 < 1e-4) {
    var sx = (n % 2 === 0) ? 0.1 : -0.1;
    return { action: "move", u: [sx, 0] };
  }
  if (a22 < 1e-4) {
    var sy = (n % 2 === 0) ? 0.1 : -0.1;
    return { action: "move", u: [0, sy] };
  }

  var lam = 1e-5;
  var b11 = a11 + lam, b22 = a22 + lam;
  var detA = b11 * b22 - a12 * a12;
  // ill-conditioned window: probe perpendicular to last applied command
  if (!isFinite(detA) || detA < 1e-3 * b11 * b22) {
    var lc = valid[nv - 1].applied;
    var pl = Math.max(Math.abs(lc[0]), Math.abs(lc[1]));
    var px = -lc[1] / pl * 0.1, py = lc[0] / pl * 0.1;
    if (isFinite(px) && isFinite(py)) return { action: "move", u: [px, py] };
    return { action: "move", u: [0.1, -0.1] };
  }
  var i11 = b22 / detA, i12 = -a12 / detA, i22 = b11 / detA;

  // J = B * inv(A): delta ≈ J * applied
  var j00 = bx0 * i11 + bx1 * i12;
  var j01 = bx0 * i12 + bx1 * i22;
  var j10 = by0 * i11 + by1 * i12;
  var j11 = by0 * i12 + by1 * i22;
  if (!isFinite(j00) || !isFinite(j01) || !isFinite(j10) || !isFinite(j11)) {
    return { action: "move", u: [0.1, -0.1] };
  }

