  var frob2 = j00 * j00 + j01 * j01 + j10 * j10 + j11 * j11;
  if (frob2 === 0 || !isFinite(frob2)) {
    return { action: "move", u: [0.1, -0.1] };
  }
  var mu = 1e-4 * frob2 + 1e-12;
  var g11 = j00 * j00 + j01 * j01 + mu;
  var g12 = j00 * j10 + j01 * j11;
  var g22 = j10 * j10 + j11 * j11 + mu;
  var gdet = g11 * g22 - g12 * g12;
  if (!isFinite(gdet) || Math.abs(gdet) < 1e-18) {
    return { action: "move", u: [0.1, -0.1] };
  }
  var z0 = (g22 * ex - g12 * ey) / gdet;
  var z1 = (-g12 * ex + g11 * ey) / gdet;
  var u0 = j00 * z0 + j10 * z1;
  var u1 = j01 * z0 + j11 * z1;
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "move", u: [0.1, -0.1] };
  }

  var m = Math.max(Math.abs(u0), Math.abs(u1));
  if (m > 0.1) {
    var s2 = 0.1 / m;
    u0 *= s2; u1 *= s2;
  } else {
    u0 *= 0.95; u1 *= 0.95;
  }
  u0 = Math.max(-0.1, Math.min(0.1, u0));
  u1 = Math.max(-0.1, Math.min(0.1, u1));
  if (!isFinite(u0) || !isFinite(u1)) {
    return { action: "stop", reason: "non-finite control output" };
  }
  return { action: "move", u: [u0, u1] };
}

function control(state) {
  var tip = state && state.tip;
  var target = state && state.target;
  if (!tip || !target || tip.length < 2 || target.length < 2 ||
      !isFinite(tip[0]) || !isFinite(tip[1]) || !isFinite(target[0]) || !isFinite(target[1])) {
    return { action: "stop", reason: "invalid tip or target" };
  }
  var ex = target[0] - tip[0];
  var ey = target[1] - tip[1];
  var err = Math.sqrt(ex * ex + ey * ey);
  if (!isFinite(err)) return { action: "stop", reason: "non-finite error" };
  if (err <= state.tolerancePx) return { action: "verify" };

  var hist = state.history || [];
  // Use only the most recent samples so the local Jacobian follows posture changes.
  var start = Math.max(0, hist.length - 10);
  var a11 = 0, a12 = 0, a22 = 0;
  var b10 = 0, b11 = 0, b20 = 0, b21 = 0;
  var n = 0;
  var blocked = [0, 0];
  var energy = [0, 0];
  for (var i = start; i < hist.length; i++) {
    var h = hist[i];
    if (!h || !h.applied || !h.delta) continue;
    var a = h.applied, d = h.delta, c = h.command;
    if (a.length < 2 || d.length < 2) continue;
    if (!isFinite(a[0]) || !isFinite(a[1]) || !isFinite(d[0]) || !isFinite(d[1])) continue;
    for (var j = 0; j < 2; j++) {
      if (h.limited && c && typeof c[j] === "number" && Math.abs(c[j]) > 1e-9 &&
          Math.abs(a[j]) < Math.abs(c[j]) * 0.999) {
        blocked[j] = c[j] > 0 ? 1 : -1;
      } else if (!h.limited && Math.abs(a[j]) > 1e-9 && blocked[j] !== 0 &&
                 (a[j] > 0 ? 1 : -1) === blocked[j]) {
        blocked[j] = 0;
      }
    }
    // Weight recent samples more strongly.
    var w = 0.5 + 0.5 * (i - start + 1) / (hist.length - start);
    a11 += w * a[0] * a[0];
    a12 += w * a[0] * a[1];
    a22 += w * a[1] * a[1];
    b10 += w * a[0] * d[0];
    b11 += w * a[1] * d[0];
    b20 += w * a[0] * d[1];
    b21 += w * a[1] * d[1];
    energy[0] += a[0] * a[0];
    energy[1] += a[1] * a[1];
    n++;
  }

  function probe() {
    var k = (energy[0] <= energy[1]) ? 0 : 1;
    var s = (blocked[k] > 0) ? -1 : 1;
    var pu = [0, 0];
    pu[k] = 0.1 * s;
    return { action: "move", u: pu };
  }

  if (n < 2) return probe();

  var scale = a11 + a22;
  var lam = 1e-6 * scale + 1e-12;
  var m11 = a11 + lam, m22 = a22 + lam, m12 = a12;
  var md = m11 * m22 - m12 * m12;
  if (!isFinite(md) || Math.abs(md) < 1e-18) return probe();
  // Solve M * [p q] = b for each output row, M symmetric.
  // Row 1 of J (x response): J00 = p, J01 = q.
  var p = (m22 * b10 - m12 * b11) / md;
  var q = (-m12 * b10 + m11 * b11) / md;
  // Row 2 of J (y response): J10 = r, J11 = s2.
  var r = (m22 * b20 - m12 * b21) / md;
  var s2 = (-m12 * b20 + m11 * b21) / md;

  var detJ = p * s2 - q * r;
  var jn = Math.sqrt(p * p + q * q) * Math.sqrt(r * r + s2 * s2);
  if (!isFinite(detJ) || !isFinite(jn) || jn <= 0 || Math.abs(detJ) < 0.05 * jn) {
    return probe();
  }

