  if (blocked[0] !== 0 && u0 * blocked[0] > 0) u0 = 0;
  if (blocked[1] !== 0 && u1 * blocked[1] > 0) u1 = 0;
  if (Math.abs(u0) < 1e-6 && Math.abs(u1) < 1e-6) return probe();

  var mx = Math.max(Math.abs(u0), Math.abs(u1));
  if (mx > 0.1) {
    u0 = u0 * 0.1 / mx;
    u1 = u1 * 0.1 / mx;
  }
  if (!isFinite(u0) || !isFinite(u1)) return probe();
  return { action: "move", u: [u0, u1] };
}
